mod model;mod logic;
fn main(){let a:Vec<String>=std::env::args().collect();let initial:i64=a[1].parse().unwrap();let events:Vec<model::Event>=a[2].split(';').filter(|s|!s.is_empty()).map(|s| {let v:Vec<_>=s.split(':').collect();let n:i64=v[1].parse().unwrap();match v[0] {"0"=>model::Event::Credit(n),"1"=>model::Event::Debit(n),"2"=>model::Event::Lock,"3"=>model::Event::Unlock ,_=>panic!("bad event")}}).collect();
if a.len()>3 {let repeats:i64=a[4].parse().unwrap();let mut total=0i64;for i in 0..repeats {let v=logic::run(std::hint::black_box(&events),initial+i%3);total+=std::hint::black_box(v.balance+v.rejected+v.peak+v.audit.iter().sum::<i64>());}println!("{}",total);} else {let v=logic::run(&events,initial);println!("{{\"balance\":{},\"rejected\":{},\"peak\":{},\"audit\":{:?}}}",v.balance,v.rejected,v.peak,v.audit);}}
